const extraControl={guidecursor:'Drag within this scene to inspect the spacecraft and its readings at a shared physical instant.',speed:'Select how many mission seconds elapse per real second.',solve:'Choose the unknown in the sizing balance. Other independent inputs remain editable.',quicksolve:'Choose the quantity the model solves for in this workspace.',epoch:'Set the UTC launch epoch. Earth rotation and Sun geometry use this time.',category:'Choose the technology family to compare at equal design conditions.',windowdate:'UTC start of the 86,400-second inspection window.',cursortime:'Elapsed mission seconds for the shared cursor.',eventfilter:'Show only the selected kind of event in the current window.',shareurl:'The URL contains the design and viewing state. Copy it to reopen this instant.'};
export function explainParam(key){
 const c=controls.find(c=>c.key===key);if(!c)return '';
 const context={'Orbit & attitude':'This changes the geometry, disturbance environment or pointing response.','Compute & storage':'This changes compute performance or the storage and traffic budget.','Communications':'This changes the link or ground-access calculation.','Thermal':'This changes heat transfer or the temperature margin.','Power & aging':'This changes bus power, pack performance or age-dependent capacity.','Propulsion & structure':'This changes propulsion or the launch mass budget.'}[c.group]||'The engineering budgets update when you change this value.';
 return paramHelp[key]||(c.options?'Choose the '+c.label.toLowerCase()+' preset to load its compatible assumptions.':c.label+(c.unit?' ('+c.unit+')':'')+'. '+context);
}
export function explainMetric(key,label,unit){
 const prefix=key[0],k=['@','$','^'].includes(prefix)?key.slice(1):key;
 let definition=prefix==='@'?explainParam(k):quantities[k]||paramHelp[k];
 if(!definition)definition=(label||k)+(unit?' in '+unit:'')+'. '+(prefix==='$'?'Derived from the installed spacecraft configuration.':prefix==='^'?'Integrated or measured across the selected 24-hour window.':'Read from the numerical model at the shared mission cursor.');
 return definition;
}
const selector='.legend>span,.viewtag,.imagestate,.viewcaption,.headicon,.guidemeter span,.metacode,.tlfoot .agebox>span,[data-tip],[data-param],label[for],[data-metric],[data-action],[data-page],[data-camera],[data-scope],[data-mode],[data-layer],[data-preset],[data-event],[data-inspect],[data-chart],[data-ei],.tracks,select,input,summary,a,button,[title]';
export function installHelp({chartTip,eventTip,fieldTip}={}){
 const tip=document.createElement('div');tip.id='workbench-tip';tip.setAttribute('role','tooltip');tip.hidden=true;document.body.append(tip);
 let active=null,lens=false,pressed=false,hold=0,lastX=0,lastY=0;
 const hide=()=>{tip.hidden=true;if(active?.getAttribute?.('aria-describedby')===tip.id)active.removeAttribute('aria-describedby');active=null};
 const show=(target,x,y,text)=>{if(!text){hide();return}const host=target?.closest?.('dialog[open],:fullscreen')||document.fullscreenElement||document.body;if(tip.parentNode!==host)host.append(tip);
 if(active!==target){hide();active=target;target?.setAttribute?.('aria-describedby',tip.id)}tip.textContent=text;tip.hidden=false;
 const w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-w-8,x+12))+'px';tip.style.top=(y+h+22>innerHeight?Math.max(8,y-h-12):y+16)+'px';};
 function message(el,e){const d=el.dataset,guide=fieldTip?.(el);if(guide)return guide;
 if(d.tip)return d.tip;if(d.phase)return 'Open Phase '+d.phase+' using this same design.';if(d.rating)return 'Change the installed component’s temperature rating in kelvin.';if(d.boundRole)return 'Use a specified rating or derive a required temperature tolerance from observed extrema.';if(d.useLauncher)return 'Use this launcher for the current design and recompute clearance.';
 if(el.matches('.legend>span'))return 'Color key for '+el.textContent.trim()+'. Follow the matching marks or trace in the chart.';
 if(el.matches('.imagestate'))return 'Mission position of the shared cursor. In orbit this shows revolution count and altitude.';
 if(el.matches('.viewcaption'))return 'Selected spacecraft and its current flight state.';
 if(el.matches('.viewtag'))return 'Current 3D viewpoint. Use the camera buttons below to inspect another scale.';
 if(el.matches('.guidemeter span'))return 'The mission clock and player position within the currently selected scene.';
 if(el.matches('.agebox>span'))return 'First mission day covered by the selected time window.';
if(d.metric)return explainMetric(d.metric,d.label,d.unit);
 if(d.param)return explainParam(d.param)+(el.disabled?' The current sizing or flight mode locks this input.':'');
 if(el.tagName==='LABEL'){const linked=document.getElementById(el.htmlFor);if(linked?.dataset.param)return explainParam(linked.dataset.param)}
 if(d.action)return actionHelp[d.action]||el.getAttribute('aria-label')||el.textContent.trim();
 if(d.page)return 'Open '+pages[d.page]?.[0]+'. '+(pages[d.page]?.[2]||'The mission clock is preserved.');
 if(d.camera)return ({launch:'Inspect the stowed payload and launcher, including the tapered usable envelope.',orbit:'See Earth, the orbital track, shadow crossings and the active ground station.',spacecraft:'Inspect the enclosed spacecraft, deployed surfaces, mechanisms and beams.',core:'Cut away enclosure panels to see the internal trays, batteries and thermal transport.'})[d.camera]+' Switching camera preserves the mission instant.';
 if(d.ei!=null)return eventTip?.(Number(d.ei))||'Select this event to inspect the operation.';
 if(d.chart)return chartTip?.(el,e)||'Select a point on this trace to place the mission cursor at that time.';
 if(d.event)return 'Inspect this recorded episode and compare telemetry before, during and after it.';
 if(d.inspect)return 'Select this mass allocation to highlight and inspect its hardware.';
 if(d.scope)return ({now:'Inspect a local one-hour window around the cursor.',day:'Inspect 86,400 consecutive seconds starting at the selected window time.',mission:'Compare the full mission, including aging and accumulated use.'})[d.scope];
 if(d.mode)return d.mode==='size'?'Edit installed hardware and recalculate its dimensions and budgets.':'Keep the installed hardware fixed and adjust its operating policy.';
 if(d.layer)return 'Toggle '+overlayNames[d.layer]+' in the vehicle view.';
 if(d.preset)return 'Apply this compatible technology preset and recalculate the design.';
 if(extraControl[el.id])return extraControl[el.id];if(el.matches('.tracks'))return 'Select a colored event or click empty space to move the mission cursor. Arrow keys step through time.';
 if(el.tagName==='SUMMARY')return 'Expand or collapse '+el.textContent.trim()+'.';
 if(el.matches('a.sourcecard'))return 'Open the cited engineering source in a new tab.';
 if(el.id==='home')return 'Return to the guided mission explorer.';return el.title||el.getAttribute('aria-label')||'';
 }
 function locate(e){return e.target.closest?.(selector)}
 function hover(e){if(e.pointerType==='touch')return;const el=locate(e);if(!el){if(e.target.tagName!=='CANVAS')hide();return}show(el,e.clientX,e.clientY,message(el,e));}
 document.addEventListener('pointermove',hover);document.addEventListener('pointerout',e=>{if(!e.relatedTarget)hide()});
 document.addEventListener('focusin',e=>{const el=locate(e);if(el&&el.matches(':focus-visible')){const r=el.getBoundingClientRect();show(el,r.left,r.bottom,message(el,e))}});
 document.addEventListener('focusout',hide);document.addEventListener('scroll',hide,true);
 document.addEventListener('pointerdown',e=>{lastX=e.clientX;lastY=e.clientY;pressed=false;clearTimeout(hold);if(e.pointerType==='touch'){const el=locate(e);if(el)hold=setTimeout(()=>{pressed=true;show(el,lastX,lastY,message(el,e))},600)}});
 document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&Math.hypot(e.clientX-lastX,e.clientY-lastY)>10)clearTimeout(hold)});
 document.addEventListener('pointerup',()=>clearTimeout(hold));document.addEventListener('pointercancel',()=>clearTimeout(hold));
 const setLens=v=>{lens=v;const b=document.querySelector('[data-action="help"]');b?.setAttribute('aria-pressed',String(lens));document.body.classList.toggle('helplens',lens);if(!v)hide()};
 document.addEventListener('click',e=>{const el=locate(e);if(el?.dataset.action==='help'){e.preventDefault();e.stopImmediatePropagation();setLens(!lens);if(lens)show(el,e.clientX,e.clientY,'Inspection help is on. Tap a control or reading to learn about it. Tap Help again to resume normal controls.');return}if(pressed||(lens&&el)){e.preventDefault();e.stopImmediatePropagation();pressed=false;if(el)show(el,e.clientX,e.clientY,message(el,e));return}hide()},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape')setLens(false)});
 return {get lens(){return lens},component:(id,x,y,row)=>{if(id){const live=row?row.label+' · '+row.temperatureK.toFixed(1)+' K · '+row.state+' band '+row.minK+'–'+row.maxK+' K · '+(row.status==='pass'?'in range':row.status)+' · ':'';show(document.getElementById('scene'),x,y,live+(componentHelp[id]||'Select this component for its engineering readouts.'));}else hide()},hide};
}

